"""Short-lived invitations. Device secrets are generated by the phone, never in a QR."""
import hashlib
import re
import secrets
import time
import uuid


class PairingError(ValueError):
    pass


class DevicePairing:
    lifetime = 180
    retry_grace = 300

    def __init__(self, database):
        self.database = database
        with database.session() as db:
            db.execute("""CREATE TABLE IF NOT EXISTS pairing_invitations (
                id TEXT PRIMARY KEY, token_hash TEXT UNIQUE NOT NULL, name TEXT NOT NULL,
                role TEXT NOT NULL, expires_at REAL NOT NULL, device_id TEXT,
                claim_id TEXT, device_token_hash TEXT
            )""")

    def create(self, name, role):
        if not isinstance(name, str) or not 1 <= len(name.strip()) <= 100 or role not in ("contributor", "viewer"):
            raise PairingError("请输入有效设备名称和权限。")
        identifier, token = str(uuid.uuid4()), secrets.token_urlsafe(32)
        expires = time.time() + self.lifetime
        with self.database.session() as db:
            db.execute("DELETE FROM pairing_invitations WHERE expires_at < ?", (time.time() - self.retry_grace,))
            if db.execute("SELECT COUNT(*) FROM pairing_invitations WHERE device_id IS NULL").fetchone()[0] >= 32:
                raise PairingError("未使用邀请过多，请取消旧邀请或稍后重试。")
            db.execute("INSERT INTO pairing_invitations (id,token_hash,name,role,expires_at) VALUES (?,?,?,?,?)",
                       (identifier, self.database.token_hash(token), name.strip(), role, expires))
        return {"id": identifier, "invitation_token": token, "expires_at": expires}

    def cancel(self, identifier):
        with self.database.session() as db:
            return db.execute("DELETE FROM pairing_invitations WHERE id=? AND device_id IS NULL", (identifier,)).rowcount > 0

    def redeem(self, token, device_token, claim_id, server_id):
        if server_id != self.database.server_id:
            raise PairingError("邀请不属于此服务器。")
        if not isinstance(token, str) or not re.fullmatch(r"[A-Za-z0-9_-]{43}", token):
            raise PairingError("邀请无效或已过期。")
        if not isinstance(device_token, str) or not re.fullmatch(r"[A-Za-z0-9_-]{43}", device_token):
            raise PairingError("设备密钥格式无效。")
        try:
            if str(uuid.UUID(claim_id)) != claim_id:
                raise ValueError()
        except (ValueError, TypeError, AttributeError):
            raise PairingError("设备请求编号无效。") from None
        token_hash = self.database.token_hash(device_token)
        with self.database.session() as db:
            db.execute("BEGIN IMMEDIATE")
            row = db.execute("SELECT * FROM pairing_invitations WHERE token_hash=?", (self.database.token_hash(token),)).fetchone()
            if not row or time.time() > row["expires_at"] + (self.retry_grace if row["device_id"] else 0):
                raise PairingError("邀请无效或已过期。")
            if row["device_id"]:
                if row["claim_id"] != claim_id or not secrets.compare_digest(row["device_token_hash"], token_hash):
                    raise PairingError("邀请已由其他设备使用。")
                device = db.execute("SELECT id FROM devices WHERE id=? AND revoked_at IS NULL", (row["device_id"],)).fetchone()
                if not device:
                    raise PairingError("设备连接已被撤销。")
                identifier = row["device_id"]
            else:
                if db.execute("SELECT 1 FROM devices WHERE token_hash=?", (token_hash,)).fetchone():
                    raise PairingError("设备密钥已使用。")
                identifier = str(uuid.uuid4())
                db.execute("INSERT INTO devices (id,name,role,token_hash,created_at) VALUES (?,?,?,?,CURRENT_TIMESTAMP)",
                           (identifier, row["name"], row["role"], token_hash))
                db.execute("UPDATE pairing_invitations SET device_id=?,claim_id=?,device_token_hash=? WHERE id=?",
                           (identifier, claim_id, token_hash, row["id"]))
        return {"device_id": identifier, "server_id": self.database.server_id}
